turns.assistant:
One script builds tokens, the frame, and self-checks it.

const { canvas, frames, tokens, checks } = diazo
await tokens.create([{name:'ink',value:'#0e0e10'},{name:'paper',value:'#f6f4ef'},{name:'accent',value:'#c8f04a'}])
const f = await frames.create({ name: 'Landing', width: 1440, height: 900 })
await frames.stream(f.id, [
  '<!DOCTYPE html><html><head><style>/* hero, proof, features, pricing, footer — ~11,900 chars */</style></head><body>…',
  '</body></html>'
])
const review = await checks.review(f.id)
return { frame: f.id, findings: review.findings.length } /* ~7,200 chars of script */
